using System;
using System.Collections.Generic;
using System.IO;
using System.Linq;
using System.Threading;
using System.Windows;
namespace AkilliKisayol {
 public static class ModelFolderTests {
  public static void Unit(Action<bool,string> check){string root=Path.Combine(Path.GetTempPath(),"MakroPlus-Folders-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);try{
   check(ModelFiles.Resolve("",root,"")=="","A missing models folder does not invent a model path");Directory.CreateDirectory(ModelFiles.DirectoryFor(root));File.WriteAllText(Path.Combine(root,"models","README.txt"),"Help");check(ModelFiles.Resolve("",root,"")=="","Folder instructions are not treated as model weights");
   string first=Path.Combine(root,"models","Any model name.gguf");File.WriteAllText(first,"GGUF");check(ModelFiles.Resolve("",root,"")==first,"Single arbitrarily named GGUF is discovered");string relative=ModelFiles.Portable(first,root);check(relative==Path.Combine("models","Any model name.gguf")&&ModelFiles.Resolve(relative,root,"")==first,"Model selection inside models is saved and resolved relative to the executable");
   string moved=Path.Combine(root,"moved");Directory.CreateDirectory(Path.Combine(moved,"models"));File.Copy(first,Path.Combine(moved,relative));check(File.Exists(ModelFiles.Resolve(relative,moved,"")),"Moving an app folder preserves its models-relative selection");
   string second=Path.Combine(root,"models","second.GGUF");File.WriteAllText(second,"GGUF");check(ModelFiles.Candidates(root).Length==2&&ModelFiles.Resolve("",root,"")=="","Multiple GGUF files require a user choice");check(ModelFiles.Resolve(relative,root,"")==first,"Adding a second model does not replace a selected model");string absent=Path.Combine(root,"absent.gguf");check(ModelFiles.Resolve(absent,root,"")==absent,"A missing explicit model is not silently replaced");string outside=Path.Combine(root,"models-other","external.gguf");check(ModelFiles.Portable(outside,root)==outside,"A similarly named external folder stays an absolute selection");
   string modelInfo=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"models","README.txt"),guide=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"USER_GUIDE.html");check(File.Exists(modelInfo)&&File.Exists(guide),"Build includes the models folder instructions and offline user guide");var html=File.ReadAllText(guide);check(new[]{"id=\"models\"","id=\"prompts\"","id=\"touchpad\"","id=\"themes\"","id=\"troubleshooting\""}.All(html.Contains)&&!html.Contains("<script")&&!html.Contains("src=\"http"),"Offline guide covers key flows without scripts or remote assets");
  }finally{Directory.Delete(root,true);}}
  public static void Ui(MainWindow owner,Action<bool,string> check,Action<Window,string> screenshot){string root=Path.Combine(Path.GetTempPath(),"MakroPlus-FolderUi-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(Path.Combine(root,"models"));var dialog=new ModelSettingsWindow(new ModelOptions(),"",root){Owner=owner};try{dialog.Show();check(dialog.SelectedFileForTest==""&&dialog.FolderStatusForTest.Contains("No GGUF"),"Empty folder setup explains where the user should put a model");string first=Path.Combine(root,"models","chosen.gguf");File.WriteAllText(first,"GGUF");dialog.RefreshModelsForTest();check(dialog.SelectedFileForTest==first,"Refresh discovers a newly copied GGUF in the actual settings dialog");File.WriteAllText(Path.Combine(root,"models","other.gguf"),"GGUF");dialog.RefreshModelsForTest();check(dialog.SelectedFileForTest==first,"Refreshing several models keeps the selected file");dialog.SelectedFileForTest="";dialog.RefreshModelsForTest();check(dialog.SelectedFileForTest==""&&dialog.FolderStatusForTest.Contains("2 GGUF"),"Settings asks for a choice when several models exist");screenshot(dialog,"model-folder-settings.png");dialog.SelectedFileForTest="\0invalid";dialog.CommitForTest();check(dialog.Result==null&&dialog.FeedbackForTest.Contains("Invalid model path"),"Invalid manual model path stays in the dialog without crashing or saving settings");}finally{dialog.Close();Directory.Delete(root,true);}
   string folder=Path.Combine(Path.GetTempPath(),"MakroPlus-ClosedApp-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);string app=Path.Combine(folder,"OfflineFixture.exe");File.Copy(System.Reflection.Assembly.GetExecutingAssembly().Location,app);try{check(!AppLibrary.Running().Any(p=>Rules.SameApp(p,app)),"Closed-app fixture is not a running application");var picker=new AppPicker(new[]{app}){Owner=owner};picker.Show();try{check(picker.ListedForTest(app),"Registered closed applications remain visible in the application picker");}finally{picker.Close();}using(var keyboard=new KeyboardEngine()){var initial=new Binding{Name="Closed app assignment",Key=119,Kind="Application",Target=app};var editor=new Editor(keyboard,null,new Binding[0],new[]{app},initial){Owner=owner};editor.Show();try{check(Rules.Validate(editor.CurrentDraft(),new Binding[0])==null,"Manual shortcut creation accepts a closed target executable");}finally{editor.Close();}var scoped=initial.Copy();scoped.Kind="Send key";scoped.SendMods=2;scoped.SendKey=83;scoped.AppPath=app;editor=new Editor(keyboard,null,new Binding[0],new[]{app},scoped){Owner=owner};editor.Show();try{check(Rules.Validate(editor.CurrentDraft(),new Binding[0])==null,"Application-specific shortcut creation accepts a closed scope executable");}finally{editor.Close();}var prompt=new PromptWindow(keyboard,new Binding[0],new[]{app}){Owner=owner};prompt.Show();try{check(prompt.SelectTargetForTest(app),"Prompt destination selection accepts a registered closed application");screenshot(prompt,"closed-application-prompt.png");}finally{prompt.Close();}}check(Native.AppWindows(app).Count==0,"Creating shortcuts did not launch the selected application");}finally{Directory.Delete(folder,true);}
  }
  public static int Real(){string report=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"model-folder-test.json");var results=new List<object>();string root=Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"closed-app-fixture-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(root);string app=Path.Combine(root,"OfflineFixture.exe");File.Copy(System.Reflection.Assembly.GetExecutingAssembly().Location,app);using(var model=new LocalLlm())try{string resolved=ModelFiles.Resolve("");if(!File.Exists(resolved))throw new FileNotFoundException("Put exactly one real test GGUF in models first.");string[] prompts={"When I press F8, press Ctrl+S.","Open the selected application when I press F9.","When I press F7, copy the selected text."};for(int i=0;i<prompts.Length;i++){var plan=model.AnalyzeAsync(new LlmRequest{Prompt=prompts[i],ModelPath=i==0?"":ModelFiles.Portable(resolved),Applications=i==0?new List<string>():new List<string>{app},TargetApp=i==1?app:"",SelectedApp=i==2?app:"",Options=new ModelOptions()},p=>{},CancellationToken.None).GetAwaiter().GetResult();bool valid=plan.Ready&&(i==0?plan.Binding.Steps.Count==1&&plan.Binding.Steps[0].Mods==2&&plan.Binding.Steps[0].Key==83:i==1?plan.Binding.AppPath==""&&plan.Binding.Steps.Any(s=>s.Kind=="Open application"&&Rules.SameApp(s.AppPath,app)):Rules.SameApp(plan.Binding.AppPath,app)&&plan.Binding.Steps.Single().Key==67)&&Native.AppWindows(app).Count==0;results.Add(new{scenario=i==0?"Auto-discovered model in models folder":i==1?"Models-relative selection and closed launch target":"Closed application scope during prompt planning",passed=valid,errors=plan.Errors});if(!valid)throw new Exception("Folder/closed-app model test failed: "+i);}if(model.StartupCount!=1)throw new Exception("The auto-discovered and relative paths did not reuse one model session.");File.WriteAllText(report,LocalLlm.Json().Serialize(new{status="PASS",model=Path.GetFileName(resolved),results=results}));return 0;}catch(Exception error){File.WriteAllText(report,LocalLlm.Json().Serialize(new{status="FAIL",error=error.ToString(),response=model.LastResponse,results=results}));return 1;}finally{Directory.Delete(root,true);}}
 }
}
